
    create table alarm (
       id varchar(255) not null comment 'UUID',
        log_id bigint not null comment 'AlarmLog id',
        state integer not null comment '告警狀態',
        primary key (id)
    ) engine=InnoDB;

    create table alarm_level_config (
       id varchar(255) not null comment 'UUID',
        alarm_level integer not null comment '警報級別',
        alarm_sub_type varchar(255) not null comment '警報類型',
        alarm_threshold double precision not null comment '警報閾值',
        custom_notification bit comment '客製的通知',
        notify_target longtext comment '通知對象',
        record_time bit comment '是否記錄告警時間',
        suppress bit not null comment '是否抑制',
        primary key (id)
    ) engine=InnoDB;
		
	create table ncu_card_reader_mapping_config (
	 id varchar(255) not null comment 'UUID',
	  ncu_id varchar(255) not null comment '主機編號',
	  control_id varchar(255) not null comment '控制器編號',
	  device_id varchar(255) not null comment '控制器對應的識別ID',
	  primary key (id)
	) engine=InnoDB;

    create table alarm_log (
       id bigint not null auto_increment comment 'UUID',
        alarm_classification integer comment '警報分類',
        alarm_session_id varchar(255) comment '警報會話編號',
        alarm_state varchar(255) not null comment '告警狀態',
        alarm_sub_type varchar(255) not null comment '警報類別',
        context_data longtext comment '詳細資料',
        degree integer comment '等級',
        device_name varchar(255) comment '設備名稱',
        message varchar(255) comment '告警訊息',
        note varchar(255) comment '處理狀態',
        operator varchar(255) comment '操控者',
        priority varchar(255) comment '處理優先順序',
        timestamp datetime not null comment '警報發生或變化時間 ',
        primary key (id)
    ) engine=InnoDB;

    create table alarm_sub_type_config (
       id integer not null comment 'id',
        alarm_bcolor varchar(255) comment '警報前景顏色 RRGGBB.',
        alarm_fcolor varchar(255) comment '警報前景顏色 RRGGBB.',
        alarm_message varchar(255) comment '發出告警時額外的告警訊息, 如"斷線", 預設為空字串',
        alarm_sub_type_name varchar(255) comment '警報次類別英文名稱',
        alarm_type varchar(255) comment '所屬警報型態',
        back_normal_alarm bit comment '告警恢復正常時(degree = 0)，是否需要發 mail 或簡訊 ',
        description varchar(255) comment '警報次類別說明',
        display_enabled bit comment '是否顯示警報',
        event_bcolor varchar(255) comment '事件前景顏色 RRGGBB.',
        event_exe_mode varchar(255) comment '反應計畫 事件反應內容執行模式，只有在 isEvent = true 才有效 ',
        event_fcolor varchar(255) comment '事件前景顏色 RRGGBB.',
        event_lock_enabled bit comment '是否啟用反應計畫事件鎖定 (CCTV)',
        event_lock_time integer comment '事件鎖定預設時間(分)',
        event_log_mode varchar(255) comment '反應計畫事件登錄模式，只有在 rspEvent = true 才有效 ',
        first_remind_time integer comment '首次提醒時間，單位: 分鐘 ',
        flash_enabled bit comment '是否閃爍警報',
        icon varchar(255) comment '警報圖示檔案名稱 ',
        incident_bkg_id integer comment '事故背景圖編碼(0代表不使用)',
        incident_icon_id integer comment '事故圖示編碼(0代表不使用)',
        is_browser_marquee bit comment '是否加入瀏覽器跑馬燈顯示',
        is_marquee bit comment '是否加入跑馬燈顯示(前提必需是反應計畫事件型態才能設定) ',
        mail_other_users varchar(255) comment '寄 Mail 的其他使用者(用 , 隔開)',
        mail_roles varchar(255) comment '寄 Mail 的角色(用 , 隔開)',
        mail_users varchar(255) comment '寄 Mail 的使用者(用 , 隔開)',
        manual_enabled bit comment '是否允許手動登錄反應計畫事件',
        marquee_severity integer comment '嚴重程式(跑馬燈)(前提必需是反應計畫事件型態才能設定) ',
        remind_enabled bit comment '是否需要提醒事件尚未結束，只應用於手動輸入事件情況',
        second_remind_time integer comment '第二次提醒時間，單位: 分鐘 ',
        send_mail bit comment '是否要寄 Mail',
        send_sms bit comment '是否要寄簡訊',
        severity integer comment '警報嚴重程度',
        short_name varchar(255) not null comment '警報次類別簡稱',
        sms_other_users varchar(255) comment '寄簡訊的其他使用者(用 , 隔開)',
        sms_roles varchar(255) comment '寄簡訊的角色(用 , 隔開)',
        sms_users varchar(255) comment '寄簡訊的使用者(用 , 隔開)',
        third_remind_time integer comment '第三次及其之後間隔提醒時間，單位: 分鐘',
        voice varchar(255) comment '警報聲音檔案名稱 ',
        primary key (id)
    ) engine=InnoDB;

    create table alarm_type_config (
       alarm_type varchar(255) not null comment '警報型態 ',
        description varchar(255) not null comment '警報種類說明 ',
        rps_event bit not null comment '是否屬也是 反應計畫 事件型態 ',
        rsp_logic_type varchar(255) comment '對應到 反應計畫產生軟體內的 邏輯名稱 （規則庫內的某個規則名稱）',
        severity integer not null comment '嚴重程度 ',
        primary key (alarm_type)
    ) engine=InnoDB;

    create table branch_config (
       id varchar(255) not null comment 'UUID',
        area_type varchar(255) not null comment '分區 ',
        branch_name varchar(20) not null comment '工務段名稱',
        end_mileage integer comment '轄區結束公里數',
        expressway_id varchar(255) comment '快速道ID',
        line_id varchar(255) comment '國道ID',
        start_mileage integer comment '轄區起始公里數 ',
        primary key (id)
    ) engine=InnoDB;

    create table card_reader_password_record (
       id varchar(255) not null comment 'UUID',
        device_name varchar(255),
        password varchar(255),
        time datetime,
        type varchar(255),
        primary key (id)
    ) engine=InnoDB;

    create table device_category (
       id varchar(255) not null comment '設備分類名稱 (資收 = DGS, 資顯 = DIS, 交管 = TC 等) ',
        description varchar(40) comment '設備分類中文描述 ',
        parent_id varchar(40) comment '上層設備分類名稱',
        primary key (id)
    ) engine=InnoDB;

    create table device_config (
       device_name varchar(40) not null comment '設備名稱',
        device_type varchar(255) not null comment '設備種類',
        display_name varchar(100) comment 'UI 顯示可修改的deviceName',
        enable bit comment '0=Y 1=N',
        extend longtext comment '各類型設備自定義欄位值',
        ip varchar(20) comment '網路ＩＰ',
        latitude double precision comment '緯度',
        longitude double precision comment '經度',
        memo varchar(255) comment '備註',
        port integer comment '網路通訊埠',
        project varchar(50) not null comment '工程標別',
        primary key (device_name)
    ) engine=InnoDB;

    create table device_group (
       group_id varchar(50) not null comment '群組編號',
        group_name varchar(20) comment '群組名稱',
        group_type varchar(10) comment '設備種類',
        primary key (group_id)
    ) engine=InnoDB;

    create table device_group_device_config (
       id varchar(150) not null comment 'id',
        device_name varchar(100) not null comment '設備編號',
        group_id varchar(50) not null comment '群組id',
        primary key (id)
    ) engine=InnoDB;

    create table device_host_location (
       id integer not null comment 'ID',
        latitude double precision comment '緯度',
        line_id varchar(255) comment '路線編號',
        loc_name varchar(255) not null comment '機房名稱,需唯一',
        longitude double precision comment '經度',
        primary key (id)
    ) engine=InnoDB;

    create table device_location_mapping_config (
       id varchar(40) not null comment 'UUID',
        description varchar(255) comment '地點描述(如大門等)',
        device_name varchar(40) comment '設備編號',
        display_order integer comment '顯示順序',
        location_name varchar(255) comment '所屬機房',
        sub_location varchar(255) comment '位置(如樓層等)',
        svg_name varchar(255) comment '機房底圖名稱',
        primary key (id)
    ) engine=InnoDB;

    create table device_op_status_log (
       id bigint not null auto_increment comment 'UUID',
        comm_status integer not null comment '同ems通訊狀態, 0:正常 1:異常 ',
        created_by varchar(255) comment '新增此筆資料的模組',
        data_time datetime not null comment '記錄時間 ',
        device_name varchar(40) not null comment '設備名稱',
        direction varchar(1) comment '方向（N=北上，S=南下，E=東向，W=西向）',
        discontinued_time datetime comment '預設下架時間',
        display varchar(500) comment '現場顯示內容 ',
        line_id varchar(20) comment '路線編號（屬於哪一個國道）',
        location varchar(20) comment 'F=高速公路，H=快速道路，T=隧道，R=匝道，P=保留 (程度表的key)S=服務區，L=地方道路',
        mileage integer comment '里程數（公尺）',
        op_status_hi_nibble varchar(255) comment 'opStatus bit4~bit7',
        op_status_low_nibble varchar(255) comment 'opStatus bit0~bit3',
        operation_result varchar(255) comment '操作結果',
        priority_type varchar(255) comment '顯示優先權的設計  強制手動 > 反應計畫 > 一般手動 > 排程 > 自動演算',
        user_id varchar(255) comment '使用者 ID',
        primary key (id)
    ) engine=InnoDB;

    create table device_status (
       id varchar(255) not null,
        comm_status integer,
        data_time datetime,
        device_type varchar(255),
        last_update_status integer,
        last_update_time datetime,
        primary key (id)
    ) engine=InnoDB;

    create table device_svg_position_config (
       id varchar(40) not null comment 'UUID',
        device_group_name varchar(255) comment '設備群組名稱',
        device_name varchar(255) not null comment '設備編號',
        position_x float comment '設備位於圖片上的 x 座標 ',
        position_y float comment '設備位於圖片上的 y 座標',
        svg_name varchar(255) not null comment '底圖名稱',
        traffic_direction varchar(255) comment '設備的行車方向',
        primary key (id)
    ) engine=InnoDB;

    create table device_tc_config (
       mfcc_id varchar(20),
        direction varchar(3) comment '方向',
        line_id varchar(20) comment '路線編號',
        location varchar(255) comment '',
        milepost integer comment '里程數（公尺）',
        protocol_type varchar(10) comment '通訊協定版本',
        ramp_type varchar(1) comment '匝道類型',
        section_id varchar(20) comment '路段編號',
        show_in_ems bit comment '是否顯示於EMS中',
        device_name varchar(40) not null,
        primary key (device_name)
    ) engine=InnoDB;

    create table device_tc_hardware_status (
       id varchar(255) not null comment '設備類型-硬體狀態',
        bit_no integer comment 'bit編號',
        common bit comment '共用硬體狀態',
        description varchar(255) comment '硬體狀態描述',
        device_type varchar(40) comment '設備類型,共用為 null',
        name varchar(255) comment '硬體狀態名稱(中文)',
        protocol_type varchar(255) comment '通訊協定版本',
        primary key (id)
    ) engine=InnoDB;

    create table device_tc_status (
       bit0 bit,
        bit1 bit,
        bit10 bit,
        bit11 bit,
        bit12 bit,
        bit13 bit,
        bit14 bit,
        bit15 bit,
        bit16 bit,
        bit17 bit,
        bit18 bit,
        bit19 bit,
        bit2 bit,
        bit20 bit,
        bit21 bit,
        bit22 bit,
        bit23 bit,
        bit24 bit,
        bit25 bit,
        bit26 bit,
        bit27 bit,
        bit28 bit,
        bit29 bit,
        bit3 bit,
        bit30 bit,
        bit31 bit,
        bit4 bit,
        bit5 bit,
        bit6 bit,
        bit7 bit,
        bit8 bit,
        bit9 bit,
        context_data longblob,
        display varchar(255),
        is_display_content_match varchar(255),
        op_mode integer,
