        tc_gcode_description varchar(255),
        tc_icon_description varchar(255),
        tc_icon_description2 varchar(255),
        tc_message varchar(255),
        id varchar(255) not null,
        primary key (id)
    ) engine=InnoDB;

    create table device_type (
       id varchar(255) not null comment '設備類型名稱 ',
        category varchar(40) comment '設備分類, map to DeviceCategory id ',
        description varchar(40) comment '設備類型中文描述',
        primary key (id)
    ) engine=InnoDB;

    create table dis_display_change_log (
       id bigint not null auto_increment comment 'UUID',
        board_id integer comment 'r22 display_part SNALLINT 1為上層顯示面版、2為下層顯示面板',
        data_time datetime not null comment '記錄 時間',
        device_message varchar(100) not null comment '現場顯示內容',
        device_name varchar(40) not null comment '設備編號',
        device_type varchar(10) not null comment '設備種類',
        primary key (id)
    ) engine=InnoDB;

    create table dis_full_text_config (
       id varchar(255) not null comment '全文庫編碼 ',
        background_color varchar(500),
        background_color_codes varchar(500),
        board_id integer,
        category varchar(20),
        first_word_x integer,
        first_word_y integer,
        flash_speed varchar(255),
        foreground_color varchar(500),
        foreground_color_codes varchar(500),
        full_text_type varchar(70),
        g_code_id integer,
        g_code_x integer,
        g_code_y integer,
        hor_space integer,
        icon_code_id integer,
        icon_code_x integer,
        icon_code_y integer,
        message varchar(150),
        text_space integer,
        lower_icon_code_id integer comment '下層全彩圖形碼(1-255，0代表不使用)',
        lower_icon_code_x integer comment 'FullColor2_X INTEGER 下層全彩圖型位置ｘ軸',
        lower_icon_code_y integer comment 'FullColor2_Y INTEGER 下層全彩圖型位置ｙ軸 ',
        order_id integer comment '排序',
        primary key (id)
    ) engine=InnoDB;

    create table dis_full_text_type (
       id varchar(70) not null comment 'FullTextType INTEGER 分類(0=警告 1=控制 2=宣導 etc …)',
        category varchar(20) not null comment '面板種類',
        description varchar(50) not null comment '描述',
        primary key (id)
    ) engine=InnoDB;

    create table dis_graphic (
       dis_graphic_config_id varchar(70) not null comment '對應的dis_graphic_id',
        picture longblob not null comment '圖片,PICTURE mysql MEDIUMBLOB 16,772,215 byte數加3bytes ',
        primary key (dis_graphic_config_id)
    ) engine=InnoDB;

    create table dis_graphic_config (
       id varchar(70) not null comment 'id',
        category varchar(20) comment '面板種類',
        description varchar(50) comment '圖形說明',
        file_name varchar(30) comment '檔案名稱與副檔名',
        graphic_mode integer not null comment '圖型模式',
        picture longblob not null comment 'PICTURE mysql MEDIUMBLOB 16,772,215 byte數加3bytes 圖片',
        tc_code_id integer not null comment 'R22已下載於Tc圖片編號，用來指定下載訊息到TC顯示時使用的圖片',
        primary key (id)
    ) engine=InnoDB;

    create table dis_message_compare_log (
       id bigint not null auto_increment comment 'UUID',
        command_message varchar(100) not null comment '中心最後下載指令內容',
        data_time datetime comment '記錄時間 ',
        device_display varchar(100) not null comment '現場顯示內容',
        device_name varchar(40) not null comment '設備編號',
        device_type varchar(20) not null comment '設備種類',
        is_display_content_match varchar(255) comment '現場顯示內容比對是否符合',
        primary key (id)
    ) engine=InnoDB;

    create table dis_phrase_config (
       id varchar(70) not null comment '片語庫編碼 ',
        order_no integer comment '排序',
        phrase_name varchar(50) comment '片語名稱',
        phrase_type varchar(20) comment '所屬的片語種類編號',
        primary key (id)
    ) engine=InnoDB;

    create table dis_phrase_type (
       id varchar(20) not null comment '片語種類編號 : 1.地點1, 2.地點2, 3.地點3, 4.地點補充 , 5.對象車  6.原因, 7.指示, 8.交通管制, 9.結果 , 10.其它',
        phrase_type_name varchar(20) not null comment '片語名稱 : 1.地點1, 2.地點2, 3.地點3, 4.地點補充 , 5.對象車  6.原因, 7.指示, 8.交通管制, 9.結果 , 10.其它',
        primary key (id)
    ) engine=InnoDB;

    create table dis_queue_item (
       id varchar(255) not null comment 'id',
        alarm_sub_type_id integer comment '事件次類別 ,用來提示各fm是否需要處理資顯設備候隊表動態內容',
        construction_no varchar(255) comment '移動性施工編號 ',
        context_data longblob comment '記錄各類型設備不屬於共用的屬性',
        data_time datetime comment '資料時間(輸入時間)',
        device_name varchar(255) not null comment '設備名稱',
        device_type varchar(20) comment '屬於哪一種設備類型',
        end_time datetime comment '一般手動模式的結束時間 ',
        event_session_id varchar(255) comment '反應計畫的事件最新的 Id',
        incident_id varchar(255) comment '反應計畫的事件 originalEventId',
        priority_type varchar(255) not null comment '顯示優先權的設計  強制手動 > 反應計畫 > 一般手動 > 排程 > 自動演算',
        rsp_priority integer comment '反應計畫的優先順序 ',
        sub_priority integer comment ' 反應計畫用,若rspPriority相同,再比較此欄位 ',
        turn_off bit comment '新增熄滅到候隊表排序,忽略該筆候隊表文字顯示內容 直接視為熄滅',
        primary key (id)
    ) engine=InnoDB;

    create table dis_sunshine_table (
       sunshine_date varchar(50) not null comment '日期（只需要使用月日）ex:0101',
        sunrise datetime not null comment '日出時間（只需要使用時分）',
        sunset datetime not null comment '日落時間（只需要使用時分）',
        primary key (sunshine_date)
    ) engine=InnoDB;

    create table dis_travel_time_config (
       id varchar(41) not null comment 'deviceName-boardId',
        additional_travel_time integer comment '額外旅行時間',
        background_color varchar(255) comment '背景色 rgcolor model',
        board_id integer comment '旅行時間組別編號，由1開始',
        delay_time integer comment '延遲時間(分)',
        device_name varchar(40) not null comment '設備編號',
        dis_graphic_config_id integer comment '面板ICON編號 (圖型編碼，1-255，0代表不使用)',
        enable bit comment '是否顯示旅行時間(旅行時間開關)',
        foreground_color varchar(255) comment '前景色 rgcolor model',
        max_travel_time integer comment '旅行時間上限(分) -1代表的是預設值 預設值的意思是設備里程至目的地距離分別用速限上下值作計算',
        message varchar(255) comment '訊息',
        min_travel_time integer comment '旅行時間下限(分) -1代表的是預設值 預設值的意思是設備里程至目的地距離分別用速限上下值作計算',
        show_max_travel_time bit comment '超過上限值是否顯示上限值',
        primary key (id)
    ) engine=InnoDB;

    create table dis_travel_time_division_config (
       id varchar(41) not null comment 'id',
        division_id varchar(20) comment '分割點編號',
        division_order integer comment '做為前端顯示用的的順序 ，由0開始',
        parent varchar(41) comment '旅行時間設定主表id ,DisTravelTimeConfig id',
        primary key (id)
    ) engine=InnoDB;

    create table dynamic_config (
       fme_name varchar(50) not null comment 'FME 名稱',
        group_name varchar(50) not null comment 'Cluster 群組名稱',
        name varchar(50) not null comment '組態名稱',
        value varchar(255) comment '組態值',
        primary key (fme_name, group_name, name)
    ) engine=InnoDB;

    create table fme_definition (
       fme_name varchar(50) not null comment 'FME 名稱',
        group_name varchar(50) not null comment 'Cluster 群組名稱',
        class_name varchar(100) not null comment 'FME 完整 Class 名稱',
        description varchar(255) comment '說明',
        enable bit not null comment '是否啟用',
        node_priority varchar(255) comment 'FME 節點執行次序，節點名稱',
        primary key (fme_name, group_name)
    ) engine=InnoDB;

    create table function_permission (
       id varchar(255) not null comment '功能 unique Id',
        description varchar(255) comment '備註',
        enable bit comment '啟用',
        level integer comment '層',
        name varchar(255) comment '名稱',
        parent_id varchar(255) comment '父身份Id',
        sequence integer comment '序列',
        update_time datetime comment '更新時間',
        url_mapping varchar(255) comment '網址映射',
        primary key (id)
    ) engine=InnoDB;

    create table hcce_group_info (
       group_name varchar(50) not null comment 'Cluster 群組名稱',
        allow_active bit not null comment '可否變成 Active 模式',
        cluster_mode integer not null comment 'Cluster 狀態',
        description varchar(255) comment '說明',
        primary key (group_name)
    ) engine=InnoDB;

    create table mfcc_config (
       mfcc_id varchar(20) not null comment 'MFCC軟體編號',
        group_name varchar(50) comment '此欄位須跟hcce_group_info裡面的group_name對照',
        host_id varchar(20) not null comment '所屬主機編號',
        memo varchar(50) comment '備註說明',
