    ) engine=InnoDB;

    create table modbus_pin_mapping (
       id bigint not null auto_increment comment 'ID',
        address integer not null comment 'Modbus位址',
        bit_number integer comment '第幾個bit',
        device_name varchar(255) not null comment '設備名稱',
        inversion bit not null comment '是否反相',
        key_name varchar(255) not null comment 'IMap key',
