        cpu_usage double precision not null comment 'CPU 使用率百分比',
        disk_usage_json varchar(1000) comment '硬碟使用率百分比的 map，key 為 diskName，value 為硬碟使用率，型態為 double',
        group_name varchar(255) not null comment 'Cluster 群組名稱',
        mem_used_percent double precision comment 'MEM使用百分比',
