        record_time datetime not null comment '記錄時間',
        sum_of_rx_speed_per_sec bigint not null comment '所有網路介面接收流量的總和',
        sum_of_tx_speed_per_sec bigint not null comment '所有網路介面傳輸流量的總和',
        primary key (id)
