    create table road_clover_leaf (
       id varchar(255) not null comment 'UUID',
        direction1 varchar(255) comment '方向1',
        direction2 varchar(255) comment '方向2',
        division_type varchar(255) comment '分割點種類（C=系統交流道、I=交流道、T=收費站、S=服務區） ',
        line_id1 varchar(255) comment '主線編號1',
        line_id2 varchar(255) comment '主線編號2',
        mileage1 integer comment '里程數1',
        mileage2 integer comment '里程數2',
        primary key (id)
    ) engine=InnoDB;

    create table road_division (
       division_id varchar(255) not null comment '分割點編號',
        area_type varchar(255) not null comment '轄區 (N=北區、C=中區、S=南區)',
        boundary bit comment '切割點是否屬於交接路段。 交接路段切割點位於 北區或南區與中區的交界處，交接路段切割點至轄區路段允許輸入反應計畫事件',
        division_name varchar(255) comment '分割點名稱 ',
        division_type varchar(255) not null comment '分割點種類',
        line_id varchar(255) not null comment ' 路線編號（屬於哪一個道路）',
        mileage integer comment '里程數（公尺）',
        travel_time_visible bit comment '轄區內的切割點皆可被選為 旅行時間目的地，轄區外的切割點，其 travelTimeVisible = true 時，可被選為 旅行時間目的地',
        primary key (division_id)
    ) engine=InnoDB;

