        line_name varchar(20) comment '路線名稱',
        memo varchar(50) comment '備註',
        start_mileage integer comment '開始里程（公尺）',
        primary key (line_id)
    ) engine=InnoDB;

    create table road_section (
       section_id varchar(20) not null comment '路段編號',
        area_type varchar(1) comment '轄區 (N=北區、C=中區、S=南區)',
        dds_road_section_enabled bit comment 'DDS壅塞路段顯示設定',
        dds_road_section_group1 bit comment 'DDS壅塞路段顯示設定群組一',
        dds_road_section_group2 bit comment 'DDS壅塞路段顯示設定群組二 ',
        dds_road_section_group3 bit comment 'DDS壅塞路段顯示設定群組三',
        dds_road_section_group4 bit comment 'DDS壅塞路段顯示設定群組四',
        direction varchar(1) comment '方向（N=北上，S=南下，E=東向，W=西向）',
        end_division_id varchar(20) comment '',
        event_exec_mode varchar(255) comment '反應計畫事件執行模式',
        event_log_mode varchar(255) comment '反應計畫事件登錄模式 ',
        free_speed integer comment '自由車速',
