        section_flow integer comment '車道容量(預設:2000,單位:PCU)',
        section_name varchar(40) comment '路段名稱',
        standard_vd varchar(20) comment '主標竿VD',
        start_division_id varchar(20) not null comment '開始的分割點編號（系統交流道、交流道、收費站、服務區）',
        sub_standard_vd1 varchar(20) comment '次標竿VD1',
        sub_standard_vd2 varchar(20) comment '次標竿VD2',
        primary key (section_id)
    ) engine=InnoDB;

